// Formats the UK English message files and writes `src/messages.generated.ts` from them: every key, and the
// arguments and tags each message takes, so `t()` is checked by the types. It formats each translation too, and writes
// the module that loads its files (`src/translations/<tag>.generated.ts`). Run `npm run messages` after changing a
// message file. A test fails while a file is not formatted or a generated file is behind.

import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { messageArgs, parseMessage } from "../src/message.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
export const SOURCE_DIR = join(root, "messages", "en-GB");
export const GENERATED = join(root, "src", "messages.generated.ts");
export const TRANSLATIONS = join(root, "src", "translations");

/** The translations' language tags: every directory of `messages/` but the source's. */
export function translationTags(): string[] {
  const dir = join(root, "messages");
  return readdirSync(dir).filter((d) => d !== "en-GB" && statSync(join(dir, d)).isDirectory()).sort();
}

/** The module that loads a translation's files: imported by `LOCALES` when the language is chosen. */
export function translationModule(tag: string, names = [...readSource(join(root, "messages", tag)).keys()]): string {
  return [
    `// Generated by \`npm run messages\` from messages/${tag}/*.json. Do not edit.`,
    "",
    ...names.map((name, i) => `import m${i} from "../../messages/${tag}/${name}.json" with { type: "json" };`),
    'import type { Catalog } from "../catalog.ts";',
    "",
    `export default { ${names.map((name, i) => `${JSON.stringify(name)}: m${i}`).join(", ")} } satisfies Catalog;`,
    "",
  ].join("\n");
}

/** The source files, by name: `flights` for `flights.json`. */
export function readSource(dir = SOURCE_DIR): Map<string, Record<string, string>> {
  const out = new Map<string, Record<string, string>>();
  for (const file of readdirSync(dir).filter((f) => f.endsWith(".json")).sort()) {
    const json = JSON.parse(readFileSync(join(dir, file), "utf8")) as Record<string, unknown>;
    for (const [k, v] of Object.entries(json)) if (typeof v !== "string") throw new Error(`${file}: "${k}" is not a string`);
    out.set(file.slice(0, -5), json as Record<string, string>);
  }
  return out;
}

// Characters a reader cannot see in a message file: non-breaking and narrow spaces, joiners, direction marks and
// isolates. They are written as escapes, so the file shows them.
const INVISIBLE = /[\u00a0\u2007\u2009\u200a\u200b-\u200f\u202f\u2060\u2066-\u2069\ufeff]/g;

/** A message file as `npm run messages` writes it: two-space indents, invisible characters escaped, a final line end. */
export function formatSource(messages: Record<string, string>): string {
  return `${JSON.stringify(messages, null, 2).replace(INVISIBLE, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`)}\n`;
}

export function generate(source = readSource()): string {
  const lines = [
    "// Generated by `npm run messages` from messages/en-GB/*.json. Do not edit.",
    "// Each message's arguments: number (a plural or a number), choice (a select), text, and tag (<b>…</b>).",
    "",
    "export interface MessageArgs {",
  ];
  for (const [ns, messages] of source) {
    for (const [key, text] of Object.entries(messages)) {
      let args;
      try {
        args = messageArgs(parseMessage(text));
      } catch (e) {
        throw new Error(`${ns}.json, "${key}": ${(e as Error).message}`);
      }
      const fields = [...args].sort(([a], [b]) => a.localeCompare(b)).map(([name, kind]) => `${/^[A-Za-z_]\w*$/.test(name) ? name : JSON.stringify(name)}: "${kind}"`);
      lines.push(`  ${JSON.stringify(`${ns}.${key}`)}: {${fields.length ? ` ${fields.join("; ")} ` : ""}};`);
    }
  }
  lines.push("}", "");
  return lines.join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const source = readSource();
  for (const [name, messages] of source) {
    const file = join(SOURCE_DIR, `${name}.json`);
    const text = formatSource(messages);
    if (readFileSync(file, "utf8") !== text) {
      writeFileSync(file, text);
      console.log(`Formatted ${file}`);
    }
  }
  writeFileSync(GENERATED, generate(source));
  console.log(`Wrote ${GENERATED}`);
  for (const tag of translationTags()) {
    const dir = join(root, "messages", tag);
    const files = readSource(dir);
    for (const [name, messages] of files) {
      const file = join(dir, `${name}.json`);
      const text = formatSource(messages);
      if (readFileSync(file, "utf8") !== text) {
        writeFileSync(file, text);
        console.log(`Formatted ${file}`);
      }
    }
    writeFileSync(join(TRANSLATIONS, `${tag}.generated.ts`), translationModule(tag, [...files.keys()]));
  }
}
